import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial, MeshStandardNodeMaterial, DoubleSide, Color } from 'three/webgpu';
import { gsap } from 'gsap';
import {
	uv,
	vec2,
	vec3,
	mix,
	smoothstep,
	step,
	length,
	sub,
	add,
	mul,
	abs,
	max,
	min,
	float,
	uniform,
	cond,
	greaterThan,
	lessThan,
	greaterThanEqual,
	lessThanEqual,
	negate,
} from 'three/tsl';

export default function createNode(config, ctx) {
	const { Group: THREEGroup } = ctx.THREE; // alias safety, not used directly
	const root = new Group();

	// ----- Geometry & Material -----
	const BUTTON_WIDTH = 2.6;
	const BUTTON_HEIGHT = 0.68;
	const BEVEL_DEPTH = 0.03;
	const CORNER_RADIUS = 0.08;
	const EDGE_WIDTH = 0.015; // world units
	const ACCENT_HEX = '#ff2a38';

	const geometry = new PlaneGeometry(BUTTON_WIDTH, BUTTON_HEIGHT);

	// ----- Gradient Color Node -----
	const gradientTop = new Color('#ff4450');
	const gradientMid = new Color('#ff2a38');
	const gradientBottom = new Color('#c1121f');

	const gradientNode = (() => {
		const y = uv().y;
		const topMix = mix(vec3(gradientTop), vec3(gradientMid), smoothstep(float(0.0), float(0.55), y));
		return mix(topMix, vec3(gradientBottom), smoothstep(float(0.55), float(1.0), y));
	})();

	// ----- Rounded‑Rect Mask -----
	const halfWidth = BUTTON_WIDTH * 0.5;
	const halfHeight = BUTTON_HEIGHT * 0.5;
	const radiusUV = float(CORNER_RADIUS / halfWidth); // use width for UV scaling
	const p = sub(uv(), vec2(0.5));
	const q = sub(abs(p), sub(vec2(0.5), vec2(radiusUV)));
	const k = max(q, vec2(0.0));
	const dist = sub(add(length(k), min(max(q.x, q.y), float(0.0))), radiusUV);
	const maskNode = step(dist, float(0.0));

	// ----- Edge Emissive Channel -----
	const edgeWidthUV = float(EDGE_WIDTH / halfWidth);
	const emissiveIntensity = uniform(float(1.6));
	const edgeMask = step(abs(dist), edgeWidthUV);
	const emissiveNode = mul(vec3(new Color(ACCENT_HEX)), mul(edgeMask, emissiveIntensity));

	// ----- Material Setup -----
	const material = new MeshStandardNodeMaterial({
		transparent: true,
		side: DoubleSide,
	});
	material.colorNode = gradientNode;
	material.alphaNode = maskNode;
	material.roughnessNode = float(0.5);
	material.metalnessNode = float(0.35);
	material.clearcoatNode = float(0.22);
	material.clearcoatRoughnessNode = float(0.1);
	material.emissiveNode = emissiveNode;

	const buttonMesh = new Mesh(geometry, material);
	buttonMesh.castShadow = true;
	buttonMesh.receiveShadow = true;
	root.add(buttonMesh);

	// ----- Contact Shadow -----
	const shadowGeo = new PlaneGeometry(BUTTON_WIDTH, BUTTON_HEIGHT);
	const shadowMat = new MeshBasicNodeMaterial({
		transparent: true,
		opacityNode: float(0.35),
		colorNode: vec3(new Color(0x000000)),
		side: DoubleSide,
	});
	const shadowMesh = new Mesh(shadowGeo, shadowMat);
	shadowMesh.position.z = -0.08;
	root.add(shadowMesh);

	// ----- Text Labels -----
	const ctaItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
	const labelDef = ctaItems.find(i => i.role === 'cta-label') || { text: 'BEGIN COMMISSION' };
	const captionDef = ctaItems.find(i => i.role === 'caption') || { text: 'NO DEPOSIT REQUIRED' };

	const label = ctx.fontAtlas.createText(labelDef.text ?? 'BEGIN COMMISSION', {
		fontSize: 20,
		color: '#e8ecf2',
		align: 'center',
	});
	label.position.set(0, 0, 0.001);
	root.add(label);

	const caption = ctx.fontAtlas.createText(captionDef.text ?? 'NO DEPOSIT REQUIRED', {
		fontSize: 9,
		color: '#e8ecf2',
		align: 'center',
	});
	caption.position.set(0, -(BUTTON_HEIGHT * 0.5 + 0.25), 0.001);
	root.add(caption);

	// ----- Animation Timelines -----
	// Entrance weighted‑settle
	const entranceTL = gsap.timeline({ paused: true });
	entranceTL.fromTo(
		root.scale,
		{ x: 1.04, y: 1.04, z: 1.04 },
		{
			x: 1,
			y: 1,
			z: 1,
			duration: 0.9,
			ease: 'cubic-bezier(0.165,0.84,0.44,1)',
		}
	);
	entranceTL.play();

	// Hover animation
	const hoverTL = gsap.timeline({ paused: true });
	hoverTL.to(
		root.position,
		{
			z: 0.06,
			duration: 0.18,
			ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
		},
		0
	);
	hoverTL.to(
		emissiveIntensity,
		{
			value: 2.2,
			duration: 0.18,
			ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
		},
		0
	);

	// Press animation
	const pressTL = gsap.timeline({ paused: true });
	pressTL.to(root.scale, {
		x: 0.97,
		y: 0.97,
		z: 0.97,
		duration: 0.12,
		ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
	});

	// ----- Interaction Handlers -----
	root.userData.handlers = {
		pointerover: () => hoverTL.play(),
		pointerout: () => hoverTL.reverse(),
		pointerdown: () => pressTL.play(),
		pointerup: () => pressTL.reverse(),
	};

	// ----- Cleanup -----
	root.userData.cleanup = () => {
		entranceTL.kill();
		hoverTL.kill();
		pressTL.kill();
		geometry.dispose();
		shadowGeo.dispose();
		material.dispose();
		shadowMat.dispose();
		if (label && label.traverse) {
			label.traverse(child => {
				if (child.isMesh && child.geometry) child.geometry.dispose();
				if (child.isMesh && child.material) child.material.dispose();
			});
		}
		if (caption && caption.traverse) {
			caption.traverse(child => {
				if (child.isMesh && child.geometry) child.geometry.dispose();
				if (child.isMesh && child.material) child.material.dispose();
			});
		}
	};

	return root;
}
